+}
+
+pub(super) fn write(path: &Path, data: &MemberObservations) -> anyhow::Result<()> {
+    let profiles = &data.profiles;
+    write_batch(
+        &path.join("profiles.parquet"),
+        profiles_schema(),
+        vec![
+            Arc::new(Int32Array::from_iter_values(
+                profiles.iter().map(|p| p.parliament_member_id),
+            )),
+            Arc::new(StringArray::from_iter_values(
+                profiles.iter().map(|p| &p.name),
+            )),
+            Arc::new(Int32Array::from_iter(profiles.iter().map(|p| p.party_id))),
+            Arc::new(StringArray::from_iter(
+                profiles.iter().map(|p| p.party_name.as_deref()),
+            )),
+            Arc::new(Int16Array::from_iter_values(
+                profiles.iter().map(|p| p.latest_house),
+            )),
+            Arc::new(StringArray::from_iter(
+                profiles.iter().map(|p| p.latest_membership_from.as_deref()),
+            )),
+        ],
+    )?;
+    write_batch(
+        &path.join("current_commons.parquet"),
+        current_schema(),
+        vec![Arc::new(Int32Array::from(data.current_commons.clone()))],
+    )?;
+    let rows: Vec<_> = data
+        .histories
+        .iter()
+        .flat_map(|h| {
+            h.house_memberships
+                .iter()
+                .map(move |m| (h.parliament_member_id, m))
+        })
+        .collect();
+    write_batch(
+        &path.join("house_memberships.parquet"),
+        memberships_schema(),
+        vec![
+            Arc::new(Int32Array::from_iter_values(rows.iter().map(|(id, _)| *id))),
+            Arc::new(Int16Array::from_iter_values(
+                rows.iter().map(|(_, m)| m.house),
+            )),
+            Arc::new(Date32Array::from_iter_values(
+                rows.iter().map(|(_, m)| m.start_date.to_epoch_days()),
+            )),
+            Arc::new(Date32Array::from_iter(
+                rows.iter()
+                    .map(|(_, m)| m.end_date.map(|d| d.to_epoch_days())),
+            )),
+        ],
+    )?;
+    Ok(())
+}
+fn write_batch(path: &Path, schema: SchemaRef, columns: Vec<ArrayRef>) -> anyhow::Result<()> {
+    let batch = RecordBatch::try_new(schema.clone(), columns)?;
+    let file = File::create_new(path).with_context(|| format!("create {}", path.display()))?;
+    let properties = WriterProperties::builder()
+        .set_compression(Compression::SNAPPY)
+        .build();
+    let mut writer = ArrowWriter::try_new(&file, schema, Some(properties))?;
+    writer.write(&batch)?;
+    writer.close()?;
+    file.sync_all()?;
+    Ok(())
+}
+
+pub(super) fn read(path: &Path) -> anyhow::Result<MemberObservations> {
+    let mut profiles = Vec::new();
+    for batch in read_batches(&path.join("profiles.parquet"), &profiles_schema())? {
+        let ids: &Int32Array = column(&batch, 0)?;
+        let names: &StringArray = column(&batch, 1)?;
+        let parties: &Int32Array = column(&batch, 2)?;
+        let party_names: &StringArray = column(&batch, 3)?;
+        let houses: &Int16Array = column(&batch, 4)?;
+        let locations: &StringArray = column(&batch, 5)?;
+        for row in 0..batch.num_rows() {
+            profiles.push(MemberProfile {
+                parliament_member_id: ids.value(row),
+                name: names.value(row).into(),
+                party_id: (!parties.is_null(row)).then(|| parties.value(row)),
+                party_name: (!party_names.is_null(row)).then(|| party_names.value(row).into()),
+                latest_house: houses.value(row),
+                latest_membership_from: (!locations.is_null(row))
+                    .then(|| locations.value(row).into()),
+            });
+        }
+    }
+    let mut current_commons = Vec::new();
+    for batch in read_batches(&path.join("current_commons.parquet"), &current_schema())? {
+        let ids: &Int32Array = column(&batch, 0)?;
+        current_commons.extend(ids.values());
+    }
+    let mut histories: BTreeMap<i32, Vec<HouseMembership>> = BTreeMap::new();
+    for batch in read_batches(
+        &path.join("house_memberships.parquet"),
+        &memberships_schema(),
+    )? {
+        let ids: &Int32Array = column(&batch, 0)?;
+        let houses: &Int16Array = column(&batch, 1)?;
+        let starts: &Date32Array = column(&batch, 2)?;
+        let ends: &Date32Array = column(&batch, 3)?;
+        for row in 0..batch.num_rows() {
+            let id = ids.value(row);
+            let date = |value| {
+                NaiveDate::from_epoch_days(value)
+                    .with_context(|| format!("member {id}: invalid source calendar date"))
+            };
+            histories.entry(id).or_default().push(HouseMembership {
+                house: houses.value(row),
+                start_date: date(starts.value(row))?,
+                end_date: if ends.is_null(row) {
+                    None
+                } else {
+                    Some(date(ends.value(row))?)
+                },
+            });
+        }
+    }
+    Ok(MemberObservations {
+        profiles,
+        current_commons,
+        histories: histories
+            .into_iter()
+            .map(|(parliament_member_id, house_memberships)| MemberHistory {
+                parliament_member_id,
+                house_memberships,
+            })
+            .collect(),
+    })
+}
+fn read_batches(path: &Path, schema: &SchemaRef) -> anyhow::Result<Vec<RecordBatch>> {
+    let result = (|| {
+        let builder = ParquetRecordBatchReaderBuilder::try_new(File::open(path)?)?;
+        ensure!(
+            builder.schema().fields() == schema.fields(),
+            "Parquet types, fields or nullability do not match schema v1"
+        );
+        let batches = builder.build()?.collect::<Result<Vec<_>, _>>()?;
+        for batch in &batches {
+            for (field, column) in schema.fields().iter().zip(batch.columns()) {
+                ensure!(
+                    field.is_nullable() || column.null_count() == 0,
+                    "required column {} contains nulls",
+                    field.name()
+                );
+            }
+        }
+        Ok(batches)
+    })();
+    result.with_context(|| format!("read {}", path.display()))
+}
+fn column<T: Array + 'static>(batch: &RecordBatch, index: usize) -> anyhow::Result<&T> {
+    batch
+        .column(index)
+        .as_any()
+        .downcast_ref()
+        .context("unexpected Parquet column type")
+}
diff --git a/exposed/src/lib/outbound/member_postgres.rs b/exposed/src/lib/outbound/member_postgres.rs
new file mode 100644
index 0000000..d5740eb
--- /dev/null
+++ b/exposed/src/lib/outbound/member_postgres.rs
@@ -0,0 +1,171 @@
+//! PostgreSQL reconciliation of one complete, prevalidated Commons refresh.
+use crate::domain::{
+    models::member_ingestion::{MemberImport, MemberImportSummary, MemberRecord, MemberRefresh},
+    repositories::member_writer::{MemberWriteError, MemberWriter},
+};
+use anyhow::{Context, ensure};
+use chrono::{DateTime, NaiveDate, Utc};
+use sqlx::{Connection, PgConnection, Postgres, Row, Transaction, postgres::PgConnectOptions};
+use std::{str::FromStr, time::Duration};
+use uuid::Uuid;
+
+/// Offline member writer; construction validates configuration without connecting.
+#[derive(Clone)]
+pub struct MemberDatabase {
+    options: PgConnectOptions,
+}
+impl MemberDatabase {
+    /// Store validated connection settings for a later atomic refresh.
+    ///
+    /// # Errors
+    /// Rejects an empty or invalid PostgreSQL connection string.
+    pub fn new(connection_string: &str) -> Result<Self, MemberWriteError> {
+        if connection_string.trim().is_empty() {
+            return Err(MemberWriteError(
+                "connection_string must not be empty".into(),
+            ));
+        }
+        let options = PgConnectOptions::from_str(connection_string)
+            .map_err(|_| MemberWriteError("invalid PostgreSQL connection string".into()))?
+            .application_name("exposed-member-load");
+        Ok(Self { options })
+    }
+
+    async fn write(&self, refresh: &MemberRefresh) -> anyhow::Result<MemberImportSummary> {
+        let mut connection = tokio::time::timeout(
+            Duration::from_secs(10),
+            PgConnection::connect_with(&self.options),
+        )
+        .await
+        .context("PostgreSQL connection timed out")?
+        .context("connect to PostgreSQL")?;
+        let mut transaction = connection.begin().await?;
+        let term_id = ensure_term(&mut transaction, refresh.term_start).await?;
+        let mut summary = MemberImportSummary {
+            excluded_candidates: refresh.excluded_candidates,
+            ..MemberImportSummary::default()
+        };
+        for import in &refresh.members {
+            let change = write_member(&mut transaction, term_id, import)
+                .await
+                .with_context(|| format!("member {}", import.member.parliament_member_id))?;
+            match change {
+                ProfileChange::Inserted => summary.inserted += 1,
+                ProfileChange::Updated => summary.updated += 1,
+                ProfileChange::Unchanged => summary.unchanged += 1,
+            }
+            summary.members += 1;
+            if import.member.is_current_commons {
+                summary.current_commons += 1;
+            } else {
+                summary.former_commons += 1;
+            }
+            summary.service_periods += import.periods.len();
+        }
+        transaction
+            .commit()
+            .await
+            .context("commit member refresh")?;
+        Ok(summary)
+    }
+}
+impl MemberWriter for MemberDatabase {
+    async fn refresh_members(
+        &self,
+        refresh: &MemberRefresh,
+    ) -> Result<MemberImportSummary, MemberWriteError> {
+        self.write(refresh)
+            .await
+            .map_err(|error| MemberWriteError(format!("{error:#}")))
+    }
+}
+
+enum ProfileChange {
+    Inserted,
+    Updated,
+    Unchanged,
+}
+
+const fn midnight(date: NaiveDate) -> DateTime<Utc> {
+    date.and_time(chrono::NaiveTime::MIN).and_utc()
+}
+
+async fn ensure_term(
+    transaction: &mut Transaction<'_, Postgres>,
+    start: NaiveDate,
+) -> anyhow::Result<Uuid> {
+    let terms: Vec<(Uuid, DateTime<Utc>)> =
+        sqlx::query_as("SELECT id, term_start FROM exposed.parliament_terms")
+            .fetch_all(&mut **transaction)
+            .await?;
+    ensure!(
+        terms.iter().all(|(_, date)| *date == midnight(start)),
+        "database contains another term; this operation refreshes one configured Parliament"
+    );
+    if let Some((id, _)) = terms.first() {
+        return Ok(*id);
+    }
+    let id = sqlx::query_scalar(
+        "INSERT INTO exposed.parliament_terms (id, term_start) VALUES ($1, $2) RETURNING id",
+    )
+    .bind(Uuid::now_v7())
+    .bind(midnight(start))
+    .fetch_one(&mut **transaction)
+    .await?;
+    Ok(id)
+}
+
+async fn write_member(
+    transaction: &mut Transaction<'_, Postgres>,
+    term_id: Uuid,
+    import: &MemberImport,
+) -> anyhow::Result<ProfileChange> {
+    let member = &import.member;
+    let previous = sqlx::query("SELECT parliament_member_id, name, party_id, party_name, latest_house, latest_membership_from, is_current_commons FROM exposed.members WHERE parliament_member_id = $1")
+        .bind(member.parliament_member_id).fetch_optional(&mut **transaction).await?;
+    let change = if let Some(row) = previous {
+        let stored = MemberRecord {
+            parliament_member_id: row.try_get("parliament_member_id")?,
+            name: row.try_get("name")?,
+            party_id: row.try_get("party_id")?,
+            party_name: row.try_get("party_name")?,
+            latest_house: row.try_get("latest_house")?,
+            latest_membership_from: row.try_get("latest_membership_from")?,
+            is_current_commons: row.try_get("is_current_commons")?,
+        };
+        if stored == *member {
+            ProfileChange::Unchanged
+        } else {
+            ProfileChange::Updated
+        }
+    } else {
+        ProfileChange::Inserted
+    };
+    let member_id: Uuid = sqlx::query_scalar(
+        "INSERT INTO exposed.members (id, parliament_member_id, name, party_id, party_name, latest_house, latest_membership_from, is_current_commons)
+         VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
+         ON CONFLICT (parliament_member_id) DO UPDATE SET name = EXCLUDED.name,
+           party_id = EXCLUDED.party_id, party_name = EXCLUDED.party_name,
+           latest_house = EXCLUDED.latest_house, latest_membership_from = EXCLUDED.latest_membership_from,
+           is_current_commons = EXCLUDED.is_current_commons RETURNING id")
+        .bind(Uuid::now_v7()).bind(member.parliament_member_id).bind(&member.name).bind(member.party_id)
+        .bind(&member.party_name).bind(member.latest_house).bind(&member.latest_membership_from).bind(member.is_current_commons)
+        .fetch_one(&mut **transaction).await?;
+    for period in &import.periods {
+        sqlx::query(
+            "INSERT INTO exposed.member_terms (id, member_id, term_id, house, source_start_date, source_end_date, served_from, served_until)
+             VALUES ($1, $2, $3, 1, $4, $5, $6, $5)
+             ON CONFLICT (member_id, term_id, house, source_start_date) DO UPDATE SET
+                source_end_date = EXCLUDED.source_end_date, served_from = EXCLUDED.served_from, served_until = EXCLUDED.served_until")
+            .bind(Uuid::now_v7()).bind(member_id).bind(term_id).bind(midnight(period.source_start_date))
+            .bind(period.source_end_date.map(midnight)).bind(midnight(period.served_from)).execute(&mut **transaction).await?;
+    }
+    let starts: Vec<_> = import
+        .periods
+        .iter()
+        .map(|p| midnight(p.source_start_date))
+        .collect();
+    sqlx::query("DELETE FROM exposed.member_terms WHERE member_id = $1 AND term_id = $2 AND (house <> 1 OR NOT (source_start_date = ANY($3)))")
+        .bind(member_id).bind(term_id).bind(starts).execute(&mut **transaction).await?;
+    Ok(change)
+}
diff --git a/exposed/src/lib/outbound/parliament_api.rs b/exposed/src/lib/outbound/parliament_api.rs
new file mode 100644
index 0000000..88aac41
--- /dev/null
+++ b/exposed/src/lib/outbound/parliament_api.rs
@@ -0,0 +1,291 @@
+//! Sequential Members API requests, typed decoding and bounded retries.
+use crate::domain::{
+    models::member_ingestion::{HouseMembership, MemberHistory, MemberProfile},
+    repositories::parliament_api::{ParliamentApi, ParliamentApiError},
+};
+use chrono::{DateTime, NaiveDate, NaiveDateTime};
+use reqwest::{Client, StatusCode, Url};
+use serde::{Deserialize, de::DeserializeOwned};
+use serde_json::Value;
+use std::{
+    fmt::Display,
+    time::{Duration, SystemTime},
+};
+
+/// Production HTTP source for the Commons cohort.
+#[derive(Clone)]
+pub struct MembersApi {
+    client: Client,
+    base_url: Url,
+}
+impl MembersApi {
+    /// Build an HTTP client without issuing requests.
+    ///
+    /// # Errors
+    /// Rejects invalid URLs or HTTP client configuration.
+    pub fn new(base_url: &str) -> Result<Self, ParliamentApiError> {
+        let base_url = Url::parse(base_url).map_err(|_| failure("invalid Members API URL"))?;
+        if !matches!(base_url.scheme(), "http" | "https")
+            || base_url.host_str().is_none()
+            || !base_url.username().is_empty()
+            || base_url.password().is_some()
+        {
+            return Err(failure(
+                "Members API URL must be an HTTP(S) URL without credentials",
+            ));
+        }
+        let client = Client::builder()
+            .connect_timeout(Duration::from_secs(10))
+            .timeout(Duration::from_secs(30))
+            .build()
+            .map_err(failure)?;
+        Ok(Self { client, base_url })
+    }
+
+    async fn get(
+        &self,
+        path: &str,
+        params: &[(&str, String)],
+    ) -> Result<Vec<u8>, ParliamentApiError> {
+        let mut url = self.base_url.join(path).map_err(failure)?;
+        url.query_pairs_mut()
+            .extend_pairs(params.iter().map(|(key, value)| (*key, value.as_str())));
+        // Request context contains source filters/IDs, never connection credentials.
+        let context = format!("{path}?{}", url.query().unwrap_or_default());
+        for attempt in 0..4 {
+            tokio::time::sleep(Duration::from_millis(200)).await;
+            let mut delay = Duration::from_secs(1 << attempt);
+            let problem = match self.client.get(url.clone()).send().await {
+                Ok(response) => {
+                    let status = response.status();
+                    if status == StatusCode::OK {
+                        match response.bytes().await {
+                            Ok(bytes) => return Ok(bytes.to_vec()),
+                            Err(error) => format!("response transport failure: {error}"),
+                        }
+                    } else {
+                        if status != StatusCode::TOO_MANY_REQUESTS && !status.is_server_error() {
+                            return Err(failure(format!("{context}: HTTP {status}")));
+                        }
+                        if let Some(header) = response
+                            .headers()
+                            .get(reqwest::header::RETRY_AFTER)
+                            .and_then(|h| h.to_str().ok())
+                        {
+                            delay = retry_delay(header).unwrap_or(delay);
+                        }
+                        format!("HTTP {status}")
+                    }
+                }
+                Err(error) => format!("transport failure: {error}"),
+            };
+            if attempt == 3 {
+                return Err(failure(format!("{context}: {problem} after four attempts")));
+            }
+            eprintln!("{context}: {problem}; retry {}/4", attempt + 2);
+            tokio::time::sleep(delay.min(Duration::from_secs(30))).await;
+        }
+        unreachable!("four attempts always return success or failure")
+    }
+
+    async fn search(
+        &self,
+        filters: Vec<(&str, String)>,
+    ) -> Result<Vec<MemberProfile>, ParliamentApiError> {
+        let mut profiles = Vec::new();
+        let mut offset = 0;
+        loop {
+            let mut params = filters.clone();
+            params.extend([("skip", offset.to_string()), ("take", "20".to_owned())]);
+            let bytes = self.get("/api/Members/Search", &params).await?;
+            let context = format!("/api/Members/Search {params:?}");
+            let page: SearchPage = decode(&bytes, &context)?;
+            if page.skip != offset {
+                return Err(failure(format!(
+                    "{context}: response skip {} does not match request {offset}",
+                    page.skip
+                )));
+            }
+            if page.items.is_empty() && offset < page.total_results {
+                return Err(failure(format!(
+                    "{context}: premature empty page before total {}",
+                    page.total_results
+                )));
+            }
+            offset = offset
+                .checked_add(page.items.len())
+                .ok_or_else(|| failure("search pagination overflow"))?;
+            for value in page.items {
+                let item: Item<Profile> = decode_item(value, &context)?;
+                profiles.push(MemberProfile {
+                    parliament_member_id: item.value.id,
+                    name: item.value.name_display_as,
+                    party_id: item.value.latest_party.as_ref().and_then(|p| p.id),
+                    party_name: item.value.latest_party.and_then(|p| p.name),
+                    latest_house: item.value.latest_house_membership.house,
+                    latest_membership_from: item.value.latest_house_membership.membership_from,
+                });
+            }
+            if offset >= page.total_results {
+                return Ok(profiles);
+            }
+        }
+    }
+}
+
+impl ParliamentApi for MembersApi {
+    async fn current_commons(&self) -> Result<Vec<MemberProfile>, ParliamentApiError> {
+        self.search(vec![
+            ("House", "1".into()),
+            ("IsCurrentMember", "true".into()),
+        ])
+        .await
+    }
+    async fn commons_candidates(
+        &self,
+        term_start: NaiveDate,
+        observation_date: NaiveDate,
+    ) -> Result<Vec<MemberProfile>, ParliamentApiError> {
+        self.search(vec![
+            (
+                "MembershipInDateRange.WasMemberOnOrAfter",
+                term_start.to_string(),
+            ),
+            (
+                "MembershipInDateRange.WasMemberOnOrBefore",
+                observation_date.to_string(),
+            ),
+            ("MembershipInDateRange.WasMemberOfHouse", "1".into()),
+        ])
+        .await
+    }
+    async fn member_histories(
+        &self,
+        member_ids: &[i32],
+    ) -> Result<Vec<MemberHistory>, ParliamentApiError> {
+        if member_ids.is_empty() || member_ids.len() > 100 {
+            return Err(failure("history requests require 1–100 member IDs"));
+        }
+        let params: Vec<_> = member_ids
+            .iter()
+            .map(|id| ("ids", id.to_string()))
+            .collect();
+        let bytes = self.get("/api/Members/History", &params).await?;
+        let context = format!("/api/Members/History {member_ids:?}");
+        let values: Vec<Value> = decode(&bytes, &context)?;
+        values
+            .into_iter()
+            .map(|value| {
+                let item: Item<History> = decode_item(value, &context)?;
+                Ok(MemberHistory {
+                    parliament_member_id: item.value.id,
+                    house_memberships: item
+                        .value
+                        .house_membership_history
+                        .into_iter()
+                        .map(|period| HouseMembership {
+                            house: period.house,
+                            start_date: period.start_date.0,
+                            end_date: period.end_date.map(|d| d.0),
+                        })
+                        .collect(),
+                })
+            })
+            .collect()
+    }
+}
+
+fn failure(message: impl Display) -> ParliamentApiError {
+    ParliamentApiError(message.to_string())
+}
+fn decode<T: DeserializeOwned>(bytes: &[u8], context: &str) -> Result<T, ParliamentApiError> {
+    let mut deserializer = serde_json::Deserializer::from_slice(bytes);
+    let result = serde_path_to_error::deserialize(&mut deserializer)
+        .map_err(|error| failure(format!("{context}: {error}")))?;
+    deserializer
+        .end()
+        .map_err(|error| failure(format!("{context}: {error}")))?;
+    Ok(result)
+}
+fn decode_item<T: DeserializeOwned>(value: Value, context: &str) -> Result<T, ParliamentApiError> {
+    let id = value
+        .pointer("/value/id")
+        .map_or_else(|| "unknown".into(), Value::to_string);
+    serde_path_to_error::deserialize(value)
+        .map_err(|error| failure(format!("{context}, member {id}: {error}")))
+}
+fn retry_delay(header: &str) -> Option<Duration> {
+    if let Ok(seconds) = header.parse::<f64>() {
+        return seconds
+            .is_finite()
+            .then(|| Duration::from_secs_f64(seconds.clamp(0.0, 30.0)));
+    }
+    httpdate::parse_http_date(header).ok().map(|date| {
+        date.duration_since(SystemTime::now())
+            .unwrap_or_default()
+            .min(Duration::from_secs(30))
+    })
+}
+
+#[derive(Deserialize)]
+struct Item<T> {
+    value: T,
+}
+#[derive(Deserialize)]
+#[serde(rename_all = "camelCase")]
+struct SearchPage {
+    items: Vec<Value>,
+    total_results: usize,
+    skip: usize,
+}
+#[derive(Deserialize)]
+#[serde(rename_all = "camelCase")]
+struct Profile {
+    id: i32,
+    name_display_as: String,
+    latest_party: Option<Party>,
+    latest_house_membership: LatestMembership,
+}
+#[derive(Deserialize)]
+struct Party {
+    id: Option<i32>,
+    name: Option<String>,
+}
+#[derive(Deserialize)]
+#[serde(rename_all = "camelCase")]
+struct LatestMembership {
+    house: i16,
+    membership_from: Option<String>,
+}
+#[derive(Deserialize)]
+#[serde(rename_all = "camelCase")]
+struct History {
+    id: i32,
+    house_membership_history: Vec<Membership>,
+}
+#[derive(Deserialize)]
+#[serde(rename_all = "camelCase")]
+struct Membership {
+    house: i16,
+    #[serde(rename = "membershipStartDate")]
+    start_date: SourceDate,
+    #[serde(rename = "membershipEndDate")]
+    end_date: Option<SourceDate>,
+}
+
+struct SourceDate(NaiveDate);
+impl<'de> Deserialize<'de> for SourceDate {
+    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
+        let value = String::deserialize(deserializer)?;
+        let date = NaiveDate::parse_from_str(&value, "%Y-%m-%d")
+            .or_else(|_| DateTime::parse_from_rfc3339(&value).map(|d| d.date_naive()))
+            .or_else(|_| {
+                NaiveDateTime::parse_from_str(&value, "%Y-%m-%dT%H:%M:%S%.f").map(|d| d.date())
+            })
+            .or_else(|_| {
+                NaiveDateTime::parse_from_str(&value, "%Y-%m-%d %H:%M:%S%.f").map(|d| d.date())
+            })
+            .map_err(serde::de::Error::custom)?;
+        Ok(Self(date))
+    }
+}

