270	    /// Interpret all observations before making any database writes.
271	    ///
272	    /// # Errors
273	    /// Rejects incomplete captures, invalid fields and inconsistent Commons service.
274	    pub fn prepare_refresh(&self) -> Result<MemberRefresh, EntityIngestionError> {
275	        self.observations.validate()?;
276	        let term_start = self.context.term_start;
277	        let as_of = self.context.observation_date;
278	        if term_start > as_of {
279	            return Err(invalid("term start is after observation date"));
280	        }
281	        let current: BTreeSet<_> = self.observations.current_commons.iter().copied().collect();
282	        let histories: BTreeMap<_, _> = self
283	            .observations
284	            .histories
285	            .iter()
286	            .map(|h| (h.parliament_member_id, h))
287	            .collect();
288	        let mut refresh = MemberRefresh {
289	            term_start,
290	            members: Vec::new(),
291	            excluded_candidates: 0,
292	        };
293	        for profile in &self.observations.profiles {
294	            let id = profile.parliament_member_id;
295	            let is_current = current.contains(&id);
296	            let periods = service_periods(histories[&id], term_start, as_of, is_current)?;
297	            if periods.is_empty() {
298	                refresh.excluded_candidates += 1;
299	                continue;
300	            }
301	            let member = profile.for_database(is_current)?;
302	            refresh.members.push(MemberImport { member, periods });
303	        }
304	        if refresh.members.is_empty() {
305	            return Err(invalid(
306	                "no Commons service was found for the configured term",
307	            ));
308	        }
309	        Ok(refresh)
310	    }
311	}
