345	fn service_periods(
346	    history: &MemberHistory,
347	    term_start: NaiveDate,
348	    as_of: NaiveDate,
349	    current: bool,
350	) -> Result<Vec<ServicePeriod>, EntityIngestionError> {
351	    let id = history.parliament_member_id;
352	    let mut memberships = BTreeSet::new();
353	    for membership in &history.house_memberships {
354	        if !matches!(membership.house, 1 | 2)
355	            || membership
356	                .end_date
357	                .is_some_and(|end| end < membership.start_date)
358	        {
359	            return Err(invalid(format!(
360	                "member {id}: invalid House or membership date ordering"
361	            )));
362	        }
363	        if membership.house == 1
364	            && membership.start_date <= as_of
365	            && membership.end_date.is_none_or(|end| end > term_start)
366	        {
367	            memberships.insert(membership);
368	        }
369	    }
370	    let periods: Vec<_> = memberships
371	        .into_iter()
372	        .map(|m| ServicePeriod {
373	            source_start_date: m.start_date,
374	            source_end_date: m.end_date,
375	            served_from: m.start_date.max(term_start),
376	        })
377	        .collect();
378	    for pair in periods.windows(2) {
379	        if pair[0].source_start_date == pair[1].source_start_date {
380	            return Err(invalid(format!("member {id}: conflicting service starts")));
381	        }
382	        if pair[0]
383	            .source_end_date
384	            .is_none_or(|end| pair[1].served_from < end)
385	        {
386	            return Err(invalid(format!("member {id}: overlapping service periods")));
387	        }
388	    }
389	    let active = periods
390	        .iter()
391	        .any(|p| p.source_end_date.is_none_or(|end| end > as_of));
392	    if active != current {
393	        return Err(invalid(format!(
394	            "member {id}: history disagrees with current Commons search"
395	        )));
396	    }
397	    Ok(periods)
398	}
