    51	{
    52	    async fn run_ingestion(
    53	        &self,
    54	        req: &EntityIngestionRequest,
    55	    ) -> Result<EntityIngestionOutcome, EntityIngestionError> {
    56	        let capture_id = CaptureId::new();
    57	        let EntityIngestionTarget::Members(MemberIngestionStage::Fetch { term_start }) =
    58	            req.target()
    59	        else {
    60	            return Err(EntityIngestionError::InvalidStage(
    61	                "this service supports member Fetch".into(),
    62	            ));
    63	        };
    64	        if *term_start > self.observation_date {
    65	            return Err(invalid("term start is after observation date"));
    66	        }
    67	        eprintln!("Capture {capture_id}: fetching current Commons observations");
    68	        let current_commons = unique_profiles(self.source.current_commons().await?)?
    69	            .into_keys()
    70	            .collect();
    71	        eprintln!(
    72	            "Capture {capture_id}: fetching historical Commons candidates since {term_start}"
    73	        );
    74	        let profiles = unique_profiles(
    75	            self.source
    76	                .commons_candidates(*term_start, self.observation_date)
    77	                .await?,
    78	        )?;
    79	        let ids: Vec<_> = profiles.keys().copied().collect();
    80	        let mut histories = Vec::new();
    81	        for batch in ids.chunks(100) {
    82	            let returned = self.source.member_histories(batch).await?;
    83	            let returned_ids: BTreeSet<_> =
    84	                returned.iter().map(|h| h.parliament_member_id).collect();
    85	            if returned_ids.len() != returned.len()
    86	                || returned_ids != batch.iter().copied().collect()
    87	            {
    88	                return Err(invalid(format!(
    89	                    "history response must match requested member IDs exactly: {batch:?}; returned {returned_ids:?}"
    90	                )));
    91	            }
    92	            histories.extend(returned);
    93	        }
    94	        histories.sort_by_key(|history| history.parliament_member_id);
    95	        let observations = MemberObservations {
    96	            profiles: profiles.into_values().collect(),
    97	            current_commons,
    98	            histories,
    99	        };
   100	        observations.validate()?;
   101	        let counts = observations.counts();
   102	        let capture = MemberCapture {
