   104	                capture_id,
   105	                term_start: *term_start,
   106	                observation_date: self.observation_date,
   107	                started_at: self.started_at,
   108	            },
   109	            observations,
   110	        };
   111	        let capture_id = self.storage.write_member_capture(capture).await?;
   112	        Ok(EntityIngestionOutcome::Fetch { capture_id, counts })
   113	    }
   114	}
