128	struct PendingCapture {
129	    staging: tempfile::TempDir,
130	    destination: PathBuf,
131	    id: CaptureId,
132	}
133	
134	impl PendingCapture {
135	    fn publish(self) -> std::io::Result<CaptureId> {
136	        // Dropping a cancelled staging task removes its temporary directory.
137	        // No await or fallible work follows atomic publication.
138	        fs::rename(self.staging.path(), &self.destination)?;
139	        Ok(self.id)
140	    }
141	}
