 27	    fn read_at(path: &Path, id: CaptureId) -> anyhow::Result<MemberCapture> {
 28	        let manifest: Manifest = serde_json::from_reader(
 29	            File::open(path.join("manifest.json")).context("missing completed manifest")?,
 30	        )
 31	        .context("invalid manifest")?;
 32	        ensure!(
 33	            manifest.schema_version == 1,
 34	            "unsupported member schema version {}",
 35	            manifest.schema_version
 36	        );
 37	        ensure!(
 38	            manifest.context.capture_id == id,
 39	            "manifest capture identity does not match {id}"
 40	        );
 41	        ensure!(
 42	            manifest.completed_at >= manifest.context.started_at,
 43	            "completion timestamp precedes capture start"
 44	        );
 45	        ensure!(
 46	            manifest.context.term_start <= manifest.context.observation_date,
 47	            "term starts after observation date"
 48	        );
 49	        ensure!(
 50	            manifest.datasets == DatasetFiles::default(),
 51	            "manifest must identify all three schema-v1 datasets"
 52	        );
 53	        let observations = member_parquet::read(path)?;
 54	        ensure!(
 55	            observations.counts() == manifest.counts,
 56	            "dataset row counts disagree with manifest"
 57	        );
 58	        observations.validate()?;
 59	        Ok(MemberCapture {
 60	            context: manifest.context,
 61	            observations,
 62	        })
 63	    }
