 65	    fn stage(&self, capture: &MemberCapture) -> anyhow::Result<PendingCapture> {
 66	        capture.observations.validate()?;
 67	        let id = capture.context.capture_id;
 68	        let parent = self.root.join("raw/members");
 69	        fs::create_dir_all(&parent)?;
 70	        let destination = parent.join(id.to_string());
 71	        ensure!(
 72	            !destination.exists(),
 73	            "completed capture {id} already exists"
 74	        );
 75	        let staging = tempfile::Builder::new()
 76	            .prefix(&format!(".staging-{id}-"))
 77	            .tempdir_in(&parent)?;
