 31	    )]))
 32	}
 33	fn memberships_schema() -> SchemaRef {
 34	    Arc::new(Schema::new(vec![
 35	        Field::new("parliament_member_id", DataType::Int32, false),
 36	        Field::new("house", DataType::Int16, false),
 37	        Field::new("source_start_date", DataType::Date32, false),
 38	        Field::new("source_end_date", DataType::Date32, true),
 39	    ]))
 40	}
