 42	pub(super) fn write(path: &Path, data: &MemberObservations) -> anyhow::Result<()> {
 43	    let profiles = &data.profiles;
 44	    write_batch(
 45	        &path.join("profiles.parquet"),
 46	        profiles_schema(),
 47	        vec![
 48	            Arc::new(Int32Array::from_iter_values(
 49	                profiles.iter().map(|p| p.parliament_member_id),
 50	            )),
 51	            Arc::new(StringArray::from_iter_values(
 52	                profiles.iter().map(|p| &p.name),
 53	            )),
 54	            Arc::new(Int32Array::from_iter(profiles.iter().map(|p| p.party_id))),
 55	            Arc::new(StringArray::from_iter(
 56	                profiles.iter().map(|p| p.party_name.as_deref()),
 57	            )),
 58	            Arc::new(Int16Array::from_iter_values(
 59	                profiles.iter().map(|p| p.latest_house),
 60	            )),
 61	            Arc::new(StringArray::from_iter(
 62	                profiles.iter().map(|p| p.latest_membership_from.as_deref()),
 63	            )),
 64	        ],
 65	    )?;
 66	    write_batch(
 67	        &path.join("current_commons.parquet"),
 68	        current_schema(),
 69	        vec![Arc::new(Int32Array::from(data.current_commons.clone()))],
 70	    )?;
 71	    let rows: Vec<_> = data
 72	        .histories
 73	        .iter()
 74	        .flat_map(|h| {
 75	            h.house_memberships
 76	                .iter()
 77	                .map(move |m| (h.parliament_member_id, m))
 78	        })
 79	        .collect();
 80	    write_batch(
 81	        &path.join("house_memberships.parquet"),
 82	        memberships_schema(),
 83	        vec![
 84	            Arc::new(Int32Array::from_iter_values(rows.iter().map(|(id, _)| *id))),
 85	            Arc::new(Int16Array::from_iter_values(
 86	                rows.iter().map(|(_, m)| m.house),
