166	        current_commons,
167	        histories: histories
168	            .into_iter()
169	            .map(|(parliament_member_id, house_memberships)| MemberHistory {
170	                parliament_member_id,
171	                house_memberships,
172	            })
173	            .collect(),
174	    })
175	}
176	fn read_batches(path: &Path, schema: &SchemaRef) -> anyhow::Result<Vec<RecordBatch>> {
177	    let result = (|| {
178	        let builder = ParquetRecordBatchReaderBuilder::try_new(File::open(path)?)?;
179	        ensure!(
180	            builder.schema().fields() == schema.fields(),
181	            "Parquet types, fields or nullability do not match schema v1"
182	        );
183	        let batches = builder.build()?.collect::<Result<Vec<_>, _>>()?;
184	        for batch in &batches {
185	            for (field, column) in schema.fields().iter().zip(batch.columns()) {
186	                ensure!(
187	                    field.is_nullable() || column.null_count() == 0,
188	                    "required column {} contains nulls",
189	                    field.name()
190	                );
191	            }
192	        }
193	        Ok(batches)
194	    })();
195	    result.with_context(|| format!("read {}", path.display()))
196	}
197	fn column<T: Array + 'static>(batch: &RecordBatch, index: usize) -> anyhow::Result<&T> {
198	    batch
199	        .column(index)
200	        .as_any()
201	        .downcast_ref()
202	        .context("unexpected Parquet column type")
203	}

