249	impl MemberRefresh {
250	    /// Construct the eligible cohort using the saved observation context.
251	    ///
252	    /// # Errors
253	    /// Rejects missing required member fields, conflicting service or an empty cohort.
254	    pub fn from_capture(capture: &MemberCapture) -> Result<Self, EntityIngestionError> {
255	        let term_start = capture.context().term_start();
256	        let as_of = capture.context().observation_date();
257	        let observations = capture.observations();
258	        let mut members = Vec::new();
259	        for profile in observations.profiles() {
260	            let id = profile.parliament_member_id();
261	            let current = observations.current_commons().contains(&id);
262	            let periods =
263	                service_periods(&observations.histories()[&id], term_start, as_of, current)?;
264	            if periods.is_empty() {
265	                continue;
266	            }
267	            let required = |field| invalid(format!("member {id}: {field} is required"));
268	            let member = ParliamentMember::new(
269	                profile.name().into(),
270	                id,
271	                profile.party_id().ok_or_else(|| required("party_id"))?,
272	                profile
273	                    .party_name()
274	                    .ok_or_else(|| required("party_name"))?
275	                    .into(),
276	                profile.latest_house(),
277	                profile
278	                    .latest_membership_from()
279	                    .ok_or_else(|| required("latest_membership_from"))?
280	                    .into(),
281	                current,
282	            )?;
283	            members.push(CommonsService { member, periods });
284	        }
285	        if members.is_empty() {
286	            return Err(invalid(
287	                "no Commons service was found for the configured term",
288	            ));
289	        }
290	        Ok(Self {
291	            term_start,
292	            members,
293	        })
294	    }
