125	        let candidates: BTreeSet<_> = profiles
126	            .iter()
127	            .map(MemberObservation::parliament_member_id)
128	            .collect();
129	        if candidates.len() != profiles.len() {
130	            return Err(invalid("duplicate historical candidate identity"));
131	        }
