307	fn service_periods(
308	    history: &MemberHistory,
309	    term_start: NaiveDate,
310	    as_of: NaiveDate,
311	    current: bool,
312	) -> Result<Vec<ServicePeriod>, EntityIngestionError> {
313	    let id = history.parliament_member_id();
314	    let memberships: BTreeSet<_> = history
315	        .house_memberships()
316	        .iter()
317	        .filter(|m| {
318	            m.house() == 1
319	                && m.start_date() <= as_of
320	                && m.end_date().is_none_or(|end| end > term_start)
321	        })
322	        .collect();
323	    let periods: Vec<_> = memberships
324	        .into_iter()
325	        .map(|m| ServicePeriod {
326	            source_start_date: m.start_date(),
327	            source_end_date: m.end_date(),
328	            served_from: m.start_date().max(term_start),
329	        })
330	        .collect();
331	    for pair in periods.windows(2) {
332	        if pair[0].source_start_date() == pair[1].source_start_date() {
333	            return Err(invalid(format!("member {id}: conflicting service starts")));
334	        }
335	        if pair[0]
336	            .source_end_date()
337	            .is_none_or(|end| pair[1].served_from() < end)
338	        {
339	            return Err(invalid(format!("member {id}: overlapping service periods")));
340	        }
341	    }
342	    let active = periods
343	        .iter()
344	        .any(|p| p.source_end_date().is_none_or(|end| end > as_of));
345	    if active != current {
346	        return Err(invalid(format!(
347	            "member {id}: history disagrees with current Commons search"
348	        )));
349	    }
350	    Ok(periods)
351	}
