     4	/// Member of Parliament with the required profile and current Commons status.
     5	#[derive(Clone, Debug, PartialEq, Eq)]
     6	pub struct ParliamentMember {
     7	    name: String,
     8	    member_id: i32,
     9	    party_id: i32,
    10	    party_name: String,
    11	    latest_house: i16,
    12	    latest_membership_from: String,
    13	    is_current_commons: bool,
    14	}
    15	
    16	impl ParliamentMember {
    17	    /// Create a member whose profile and current status are consistent.
    18	    ///
    19	    /// # Errors
    20	    /// Rejects invalid identities, a blank name, an unknown House, or current
    21	    /// Commons status with a latest Lords profile.
    22	    pub fn new(
    23	        name: String,
    24	        parliament_member_id: i32,
    25	        party_id: i32,
    26	        party_name: String,
    27	        latest_house: i16,
    28	        latest_membership_from: String,
    29	        is_current_commons: bool,
    30	    ) -> Result<Self, ParliamentMemberError> {
    31	        if parliament_member_id <= 0 {
    32	            return Err(ParliamentMemberError::InvalidField {
    33	                member_id: parliament_member_id,
    34	                field: "parliament_member_id",
    35	            });
    36	        }
    37	        if name.trim().is_empty() {
    38	            return Err(ParliamentMemberError::InvalidField {
    39	                member_id: parliament_member_id,
    40	                field: "name",
    41	            });
    42	        }
    43	        if party_id <= 0 {
    44	            return Err(ParliamentMemberError::InvalidField {
    45	                member_id: parliament_member_id,
    46	                field: "party_id",
    47	            });
    48	        }
    49	        if !matches!(latest_house, 1 | 2) || (is_current_commons && latest_house != 1) {
    50	            return Err(ParliamentMemberError::InvalidField {
    51	                member_id: parliament_member_id,
    52	                field: "latest_house",
    53	            });
    54	        }
    55	        Ok(Self {
    56	            name,
    57	            member_id: parliament_member_id,
    58	            party_id,
    59	            party_name,
    60	            latest_house,
    61	            latest_membership_from,
    62	            is_current_commons,
    63	        })
    64	    }
    65	    /// Member's source display name.
    66	    #[must_use]
    67	    pub fn name(&self) -> &str {
    68	        &self.name
    69	    }
    70	    /// Parliament's numeric member identity.
    71	    #[must_use]
    72	    pub const fn parliament_member_id(&self) -> i32 {
    73	        self.member_id
    74	    }
    75	    /// Required latest party identity.
    76	    #[must_use]
    77	    pub const fn party_id(&self) -> i32 {
    78	        self.party_id
    79	    }
    80	    /// Required latest party name.
    81	    #[must_use]
    82	    pub fn party_name(&self) -> &str {
    83	        &self.party_name
    84	    }
    85	    /// Latest House from the member profile.
    86	    #[must_use]
    87	    pub const fn latest_house(&self) -> i16 {
    88	        self.latest_house
    89	    }
    90	    /// Required latest membership location.
    91	    #[must_use]
    92	    pub fn latest_membership_from(&self) -> &str {
    93	        &self.latest_membership_from
    94	    }
    95	    /// Status observed in the current Commons search.
    96	    #[must_use]
    97	    pub const fn is_current_commons(&self) -> bool {
    98	        self.is_current_commons
    99	    }
   100	}
