   102	/// A member profile cannot be represented by a valid domain member.
   103	#[derive(Error, Debug)]
   104	pub enum ParliamentMemberError {
   105	    /// A required value is invalid or inconsistent with current membership.
   106	    #[error("member {member_id}: invalid {field}")]
   107	    InvalidField {
   108	        /// Parliament's numeric member identity.
   109	        member_id: i32,
   110	        /// Invalid source field.
