 46	    pub fn new(
 47	        parliament_member_id: i32,
 48	        name: String,
 49	        party_id: Option<i32>,
 50	        party_name: Option<String>,
 51	        latest_house: i16,
 52	        latest_membership_from: Option<String>,
 53	    ) -> Result<Self, ParliamentApiError> {
 54	        for (valid, field) in [
 55	            (parliament_member_id > 0, "parliament_member_id"),
 56	            (!name.trim().is_empty(), "name"),
 57	            (party_id.is_none_or(|id| id > 0), "party_id"),
 58	            (matches!(latest_house, 1 | 2), "latest_house"),
 59	        ] {
