  1	//! PostgreSQL member search and atomic Commons service reconciliation.
  2	
  3	use anyhow::{Context, ensure};
  4	use chrono::{DateTime, NaiveDate, Utc};
  5	use sqlx::{Postgres, Transaction};
  6	use uuid::Uuid;
  7	
  8	use crate::{
  9	    domain::{
 10	        models::{
 11	            entity_search::EntitySearchRequest,
 12	            member_ingestion::{CommonsService, MemberRefresh},
 13	            parliament_member::ParliamentMember,
 14	            search_similarity::SearchSimilarity,
 15	        },
 16	        repositories::parliament_member_repository::{
 17	            ParliamentMemberRepo, ParliamentMemberRepoError,
 18	        },
 19	    },
 20	    outbound::postgres::ExposedDatabase,
 21	};
 22	
 23	impl ParliamentMemberRepo for ExposedDatabase {
 24	    async fn refresh_members(
 25	        &self,
 26	        refresh: &MemberRefresh,
 27	    ) -> Result<(), ParliamentMemberRepoError> {
 28	        let result = async {
 29	            let mut transaction = self.pool().begin().await?;
 30	            let term_id = ensure_term(&mut transaction, refresh.term_start()).await?;
 31	            for service in refresh.members() {
 32	                write_member(&mut transaction, term_id, service)
 33	                    .await
 34	                    .with_context(|| {
 35	                        format!("member {}", service.member().parliament_member_id())
 36	                    })?;
 37	            }
 38	            transaction
 39	                .commit()
 40	                .await
 41	                .context("commit member refresh")?;
 42	            Ok::<_, anyhow::Error>(())
 43	        }
 44	        .await;
 45	        result.map_err(|error| ParliamentMemberRepoError::DatabaseError(format!("{error:#}")))
 46	    }
 47	
 48	    async fn get_members_by_text_search_score(
 49	        &self,
 50	        req: &EntitySearchRequest,
 51	    ) -> Result<Vec<(ParliamentMember, SearchSimilarity)>, ParliamentMemberRepoError> {
 52	        sqlx::query!(
 53	            "
 54	            SELECT  
 55	                m.name,
 56	                m.parliament_member_id,
 57	                m.party_id,
 58	                m.party_name,
 59	                m.latest_house,
 60	                m.is_current_commons,
 61	                m.latest_membership_from as constituency,
 62	                 word_similarity($1, m.name) as similarity_score,
 63	                row_number() OVER (ORDER BY word_similarity($1, m.name) DESC) as rank
 64	            FROM members m
 65	            WHERE word_similarity($1, m.name) >= $2
 66	            ORDER BY similarity_score DESC
 67	            ",
 68	            req.term(),
 69	            req.strictness()
 70	        )
 71	        .fetch_all(self.pool())
 72	        .await
 73	        .map_err(|e| ParliamentMemberRepoError::DatabaseError(e.to_string()))?
 74	        .into_iter()
 75	        .take_while(|r| {
 76	            r.rank.unwrap_or_else(|| i64::from(req.max_entries() + 1))
 77	                <= i64::from(req.max_entries())
 78	        })
 79	        .map(|r| {
 80	            let member = ParliamentMember::new(
 81	                r.name,
 82	                r.parliament_member_id,
 83	                r.party_id,
 84	                r.party_name,
 85	                r.latest_house,
 86	                r.constituency,
 87	                r.is_current_commons,
 88	            )
 89	            .map_err(|error| ParliamentMemberRepoError::DatabaseError(error.to_string()))?;
 90	            let score = SearchSimilarity::from(r.similarity_score.unwrap_or(0_f32));
 91	            Ok((member, score))
 92	        })
 93	        .collect()
 94	    }
 95	}
 96	
 97	const fn midnight(date: NaiveDate) -> DateTime<Utc> {
 98	    date.and_time(chrono::NaiveTime::MIN).and_utc()
 99	}
100	
101	async fn ensure_term(
102	    transaction: &mut Transaction<'_, Postgres>,
103	    start: NaiveDate,
104	) -> anyhow::Result<Uuid> {
105	    let terms: Vec<(Uuid, DateTime<Utc>)> =
106	        sqlx::query_as("SELECT id, term_start FROM exposed.parliament_terms")
107	            .fetch_all(&mut **transaction)
108	            .await?;
109	    ensure!(
110	        terms.iter().all(|(_, date)| *date == midnight(start)),
111	        "database contains another term; this operation refreshes one configured Parliament"
112	    );
113	    if let Some((id, _)) = terms.first() {
114	        return Ok(*id);
115	    }
116	    let id = sqlx::query_scalar(
117	        "INSERT INTO exposed.parliament_terms (id, term_start) VALUES ($1, $2) RETURNING id",
118	    )
119	    .bind(Uuid::now_v7())
120	    .bind(midnight(start))
121	    .fetch_one(&mut **transaction)
122	    .await?;
123	    Ok(id)
124	}
125	
126	async fn write_member(
127	    transaction: &mut Transaction<'_, Postgres>,
128	    term_id: Uuid,
129	    service: &CommonsService,
130	) -> anyhow::Result<()> {
131	    let member = service.member();
132	    let member_id: Uuid = sqlx::query_scalar(
133	        "INSERT INTO exposed.members (id, parliament_member_id, name, party_id, party_name, latest_house, latest_membership_from, is_current_commons)
134	         VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
135	         ON CONFLICT (parliament_member_id) DO UPDATE SET name = EXCLUDED.name,
136	           party_id = EXCLUDED.party_id, party_name = EXCLUDED.party_name,
137	           latest_house = EXCLUDED.latest_house, latest_membership_from = EXCLUDED.latest_membership_from,
138	           is_current_commons = EXCLUDED.is_current_commons RETURNING id")
139	        .bind(Uuid::now_v7()).bind(member.parliament_member_id()).bind(member.name()).bind(member.party_id())
140	        .bind(member.party_name()).bind(member.latest_house()).bind(member.latest_membership_from()).bind(member.is_current_commons())
141	        .fetch_one(&mut **transaction).await?;
142	    for period in service.periods() {
143	        sqlx::query(
144	            "INSERT INTO exposed.member_terms (id, member_id, term_id, house, source_start_date, source_end_date, served_from, served_until)
145	             VALUES ($1, $2, $3, 1, $4, $5, $6, $5)
146	             ON CONFLICT (member_id, term_id, house, source_start_date) DO UPDATE SET
147	                source_end_date = EXCLUDED.source_end_date, served_from = EXCLUDED.served_from, served_until = EXCLUDED.served_until")
148	            .bind(Uuid::now_v7()).bind(member_id).bind(term_id).bind(midnight(period.source_start_date()))
149	            .bind(period.source_end_date().map(midnight)).bind(midnight(period.served_from())).execute(&mut **transaction).await?;
150	    }
151	    let starts: Vec<_> = service
152	        .periods()
153	        .iter()
154	        .map(|p| midnight(p.source_start_date()))
155	        .collect();
156	    sqlx::query("DELETE FROM exposed.member_terms WHERE member_id = $1 AND term_id = $2 AND (house <> 1 OR NOT (source_start_date = ANY($3)))")
157	        .bind(member_id).bind(term_id).bind(starts).execute(&mut **transaction).await?;
158	    Ok(())
159	}
