    27	    ) -> Result<(), ParliamentMemberRepoError> {
    28	        let result = async {
    29	            let mut transaction = self.pool().begin().await?;
    30	            let term_id = ensure_term(&mut transaction, refresh.term_start()).await?;
    31	            for service in refresh.members() {
    32	                write_member(&mut transaction, term_id, service)
    33	                    .await
    34	                    .with_context(|| {
