    19	impl MembersApi {
    20	    /// Build an HTTP client without issuing requests.
    21	    ///
    22	    /// # Errors
    23	    /// Rejects invalid URLs or HTTP client configuration.
    24	    pub fn new(base_url: &str) -> Result<Self, ParliamentApiError> {
    25	        let base_url = Url::parse(base_url).map_err(|_| failure("invalid Members API URL"))?;
    26	        if !matches!(base_url.scheme(), "http" | "https")
    27	            || base_url.host_str().is_none()
    28	            || !base_url.username().is_empty()
    29	            || base_url.password().is_some()
    30	        {
    31	            return Err(failure(
    32	                "Members API URL must be an HTTP(S) URL without credentials",
    33	            ));
    34	        }
    35	        let client = Client::builder()
    36	            .connect_timeout(Duration::from_secs(10))
    37	            .timeout(Duration::from_secs(30))
    38	            .build()
    39	            .map_err(failure)?;
    40	        Ok(Self { client, base_url })
    41	    }
    42	
    43	    async fn get<T: DeserializeOwned>(
    44	        &self,
    45	        path: &str,
    46	        params: &[(&str, String)],
    47	    ) -> Result<T, ParliamentApiError> {
    48	        let mut url = self.base_url.join(path).map_err(failure)?;
    49	        url.query_pairs_mut()
    50	            .extend_pairs(params.iter().map(|(key, value)| (*key, value.as_str())));
    51	        // Request context contains source filters/IDs, never connection credentials.
    52	        let context = format!("{path}?{}", url.query().unwrap_or_default());
    53	        for attempt in 0..4 {
    54	            tokio::time::sleep(Duration::from_millis(200)).await;
    55	            let mut delay = Duration::from_secs(1 << attempt);
    56	            let problem = match self.client.get(url.clone()).send().await {
    57	                Ok(response) => {
    58	                    let status = response.status();
    59	                    if status == StatusCode::OK {
    60	                        match response.bytes().await {
    61	                            Ok(bytes) => {
    62	                                let mut deserializer = serde_json::Deserializer::from_slice(&bytes);
    63	                                let result = serde_path_to_error::deserialize(&mut deserializer)
    64	                                    .map_err(|error| failure(format!("{context}: {error}")))?;
    65	                                deserializer
    66	                                    .end()
    67	                                    .map_err(|error| failure(format!("{context}: {error}")))?;
    68	                                return Ok(result);
    69	                            }
    70	                            Err(error) => format!("response transport failure: {error}"),
    71	                        }
    72	                    } else {
    73	                        if status != StatusCode::TOO_MANY_REQUESTS && !status.is_server_error() {
    74	                            return Err(failure(format!("{context}: HTTP {status}")));
    75	                        }
    76	                        if let Some(header) = response
    77	                            .headers()
    78	                            .get(reqwest::header::RETRY_AFTER)
    79	                            .and_then(|h| h.to_str().ok())
    80	                        {
    81	                            delay = retry_delay(header).unwrap_or(delay);
    82	                        }
    83	                        format!("HTTP {status}")
    84	                    }
    85	                }
    86	                Err(error) => format!("transport failure: {error}"),
    87	            };
    88	            if attempt == 3 {
    89	                return Err(failure(format!("{context}: {problem} after four attempts")));
    90	            }
    91	            eprintln!("{context}: {problem}; retry {}/4", attempt + 2);
    92	            tokio::time::sleep(delay.min(Duration::from_secs(30))).await;
    93	        }
    94	        unreachable!("four attempts always return success or failure")
    95	    }
